-- ===========================================================================
-- PART 2: constraints not expressible in schema.prisma
-- ===========================================================================

-- Single-answer questions have at most one correct option.
CREATE UNIQUE INDEX "QuestionOption_one_correct_per_question"
  ON "QuestionOption"("questionId") WHERE "isCorrect";

-- A chosen option must belong to the question being answered. The nullable
-- "selectedOptionId" skips the check while the question is unanswered.
-- (Together with the Prisma-generated key on ("attemptId","questionId") this
-- means an answer can only reference a question on its own attempt's paper,
-- and an option of that same question.)
ALTER TABLE "AttemptAnswer"
  ADD CONSTRAINT "AttemptAnswer_option_belongs_to_question_fkey"
  FOREIGN KEY ("questionId", "selectedOptionId")
  REFERENCES "QuestionOption"("questionId", "id")
  ON DELETE RESTRICT ON UPDATE CASCADE;

-- Drives
ALTER TABLE "Drive"
  ADD CONSTRAINT "Drive_test_window_check"
  CHECK ("testStartsAt" IS NULL OR "testEndsAt" IS NULL OR "testEndsAt" > "testStartsAt");
-- 6 characters, upper-case letters and digits without look-alikes (no 0, 1, I, L, O).
ALTER TABLE "Drive"
  ADD CONSTRAINT "Drive_access_code_format_check"
  CHECK ("accessCode" IS NULL OR "accessCode" ~ '^[A-HJ-KM-NP-Z2-9]{6}$');

-- Candidates (new columns only; existing rows have NULLs and pass)
ALTER TABLE "Candidate"
  ADD CONSTRAINT "Candidate_profile_ranges_check"
  CHECK (("passingYear" IS NULL OR "passingYear" BETWEEN 1990 AND 2100)
     AND ("yearsOfExperience" IS NULL OR "yearsOfExperience" BETWEEN 0 AND 60));

-- Applications: the per-drive uniqueness depends on normalised copies.
ALTER TABLE "Application"
  ADD CONSTRAINT "Application_normalised_contact_check"
  CHECK ("email" = lower("email") AND "mobile" ~ '^[6-9][0-9]{9}$');

-- Test templates and sections
ALTER TABLE "TestTemplate"
  ADD CONSTRAINT "TestTemplate_duration_marks_check"
  CHECK ("durationMinutes" > 0 AND "totalMarks" > 0 AND "negativeMarking" >= 0);
ALTER TABLE "TestTemplate"
  ADD CONSTRAINT "TestTemplate_difficulty_mix_check"
  CHECK ("easyPct" >= 0 AND "mediumPct" >= 0 AND "hardPct" >= 0
     AND "easyPct" + "mediumPct" + "hardPct" = 100);
ALTER TABLE "TestTemplateSection"
  ADD CONSTRAINT "TestTemplateSection_marks_check" CHECK ("marks" > 0);

-- Attempts
ALTER TABLE "TestAttempt"
  ADD CONSTRAINT "TestAttempt_deadline_check" CHECK ("deadline" > "startedAt");
ALTER TABLE "TestAttempt"
  ADD CONSTRAINT "TestAttempt_counters_check" CHECK ("tabSwitchCount" >= 0);

-- Interview feedback ratings are 1 to 5.
ALTER TABLE "InterviewFeedback"
  ADD CONSTRAINT "InterviewFeedback_ratings_check"
  CHECK ("technical" BETWEEN 1 AND 5 AND "problemSolving" BETWEEN 1 AND 5
     AND "communication" BETWEEN 1 AND 5 AND "stackProficiency" BETWEEN 1 AND 5
     AND "attitude" BETWEEN 1 AND 5);

-- OTP attempt counter
ALTER TABLE "OtpCode"
  ADD CONSTRAINT "OtpCode_attempts_check" CHECK ("attempts" >= 0);

COMMIT;
